# Wzorzec 7/7 Niezmienników generowany poleceniem: gov.py scaffold-unit --name <Name>
class DomainError(Exception): pass
class <Feature>Error(DomainError): pass

@dataclass(frozen=True)
class <Feature>Request:
    item_id: str
    amount: float
    def __post_init__(self):
        if not self.item_id: raise <Feature>Error("item_id required")

@dataclass(frozen=True)
class <Feature>Result:
    status: str
    item_id: str

def <feature>_handler(req: <Feature>Request) -> <Feature>Result:
    # SRP <= 40 lines, pure logic, telemetry
    return <Feature>Result(status="SUCCESS", item_id=req.item_id)
